; Gods: the Amiga-specific routines, generated by scripts/gen_intro_amiga_asm.py from the original's resident code.
; The instruction sequences are the original's (the program's timing depends on how long they take, and each
; instruction is checked against the original bytes); the C calling convention (arguments on the stack,
; d2-d7/a2-a6 preserved) is added around them where C calls them.
        xref _copper_a, _copper_b, _glyph_plane_size, _scroll, _palette_ptr, _flags, _game_clock, _vibrato_table, _period_table, _music, _sample_start, _channel, _screen_front, _screen_back, _display, _draw_flag, _vblank, _blank_plane, _font_offset, _graphics, _module, _screen_b, _screen_a
        xdef _blitter_wait, _blit_copy, _blit_copy_right, _screen_clear, _screen_restore, _plane5_set, _plane5_clear
        xdef _blit_image, _blit_image_wide, _delay, _startup_delay, _interrupts_on, _load_next_stage, _vbl_wait, _irq_level3, _music_init
        section .text,code

        include "intro_offsets.i"

; ---- blitter and screens ----
; void blitter_wait(void), orig $002F1E: wait until the blitter has finished (and give it priority while waiting)
_blitter_wait:
        move.w #$8400,$dff096.l
.loop:
        btst.b #$e,$dff002.l
        bne.b .loop
        move.w #$400,$dff096.l
        rts 

; void blit_copy(const void *src, void *dst), orig $001B7C: copy the 20 x 800 words at src to dst, A -> D
_blit_copy:
        move.l a6,-(sp)
        movea.l 8(sp),a0
        movea.l 12(sp),a1
        lea.l $dff000.l,a6
        bsr.w _blitter_wait
        move.w #$ffff,$44(a6)
        move.w #$ffff,$46(a6)
        move.l a1,$54(a6)
        move.l a0,$50(a6)
        move.w #$0,$66(a6)
        move.w #$0,$64(a6)
        move.w #$0,$42(a6)
        move.w #$9f0,$40(a6)
        move.w #$400,$96(a6)
        move.w #$c814,$58(a6)
        move.w #$8400,$96(a6)
        movea.l (sp)+,a6
        rts

; void blit_copy_right(const void *src, void *dst), orig $001BC6: only the right-hand 9 words of each row
_blit_copy_right:
        move.l a6,-(sp)
        movea.l 8(sp),a0
        movea.l 12(sp),a1
        lea.l $16(a0),a0
        lea.l $16(a1),a1
        lea.l $dff000.l,a6
        bsr.w _blitter_wait
        move.w #$ffff,$44(a6)
        move.w #$ffff,$46(a6)
        move.l a1,$54(a6)
        move.l a0,$50(a6)
        move.w #$16,$66(a6)
        move.w #$16,$64(a6)
        move.w #$0,$42(a6)
        move.w #$9f0,$40(a6)
        move.w #$400,$96(a6)
        move.w #$c809,$58(a6)
        move.w #$8400,$96(a6)
        movea.l (sp)+,a6
        rts

; void screen_clear(void), orig $0030D4: clear the front screen
_screen_clear:
        movem.l d7/a0,-(a7)
        movea.l (_screen_front).l,a0
        move.w #$270f,d7
.loop:
        clr.l (a0)+
        dbra d7,.loop
        movem.l (a7)+,d7/a0
        rts 

; void screen_restore(void), orig $0030EE: copy the back screen over the front screen
_screen_restore:
        movem.l d7/a0-a1,-(a7)
        movea.l (_screen_back).l,a0
        movea.l (_screen_front).l,a1
        move.w #$270f,d7
.loop:
        move.l (a0)+,(a1)+
        dbra d7,.loop
        movem.l (a7)+,d7/a0-a1
        rts 

; void plane5_set(void), orig $001D54: set the whole fifth bitplane of the front screen (d0/d1 for the original's d6/d7)
_plane5_set:
        movea.l (_screen_front).l,a0
        lea.l $7d00(a0),a0
        move.w #$c7,d1
        moveq #$ff,d0
.loop:
        move.l d0,(a0)+
        move.l d0,(a0)+
        move.l d0,(a0)+
        move.l d0,(a0)+
        move.l d0,(a0)+
        move.l d0,(a0)+
        move.l d0,(a0)+
        move.l d0,(a0)+
        move.l d0,(a0)+
        move.l d0,(a0)+
        dbra d1,.loop
        rts 

; void plane5_clear(void), orig $001D7E: clear the fifth bitplane of the front screen
_plane5_clear:
        movea.l (_screen_front).l,a0
        lea.l $7d00(a0),a0
        move.w #$c7,d1
        moveq #$0,d0
.loop:
        move.l d0,(a0)+
        move.l d0,(a0)+
        move.l d0,(a0)+
        move.l d0,(a0)+
        move.l d0,(a0)+
        move.l d0,(a0)+
        move.l d0,(a0)+
        move.l d0,(a0)+
        move.l d0,(a0)+
        move.l d0,(a0)+
        dbra d1,.loop
        rts 

; void blit_image(uint8_t *dst, const uint8_t *src, uint16_t plane, uint16_t shift, uint16_t rows), orig $0032B6:
; draw an image one word wide (the planes are `plane` bytes apart) through a mask built from its planes
_blit_image:
        movem.l d2-d7/a2-a4,-(sp)
        movea.l 40(sp),a0          ; dst
        movea.l 44(sp),a1          ; src
        move.w 50(sp),d0           ; bytes between the planes
        move.w 54(sp),d1           ; pixel shift
        move.w 58(sp),d7           ; rows
        move.l #$ffff,d3
        clr.w (_display+DisplayData_blit_extra_modulo).l
        moveq #$1,d6
        moveq #$0,d2
        move.b d1,d2
        bra.b blit_image_body

; void blit_image_wide(...), orig $0032CA: the same for an image two words wide
_blit_image_wide:
        movem.l d2-d7/a2-a4,-(sp)
        movea.l 40(sp),a0          ; dst
        movea.l 44(sp),a1          ; src
        move.w 50(sp),d0           ; bytes between the planes
        move.w 54(sp),d1           ; pixel shift
        move.w 58(sp),d7           ; rows
        move.l #$ffff,d3
        clr.w (_display+DisplayData_blit_extra_modulo).l
        move.w #$2,d6
        moveq #$0,d2
        move.b d1,d2
blit_image_body:
        movea.l a1,a4
        lea.l (_display+DisplayData_blit_mask).l,a2
        lea.l $dff000.l,a3
        moveq #$0,d4
        moveq #$6,d5
        move.w d7,d4
        lsl.w d5,d4
        or.w d6,d4
        move.w #$8400,$96(a3)
.wait_mask_or3:
        btst.b #$6,$2(a3)
        bne.b .wait_mask_or3
        move.l a4,$50(a3)
        adda.w d0,a4
        move.l a4,$4c(a3)
        adda.w d0,a4
        move.l a4,$48(a3)
        adda.w d0,a4
        move.l a2,$54(a3)
        moveq #$ff,d5
        move.w d5,$44(a3)
        move.w d5,$46(a3)
        moveq #$0,d5
        move.w d5,$66(a3)
        move.w d5,$42(a3)
        move.w #$ffe,$40(a3)
        add.w (_display+DisplayData_blit_extra_modulo).l,d5
        bpl.b .mask_modulo_ready
        moveq #$0,d5
.mask_modulo_ready:
        move.w d5,$64(a3)
        move.w d5,$62(a3)
        move.w d5,$60(a3)
        move.w d4,$58(a3)
.wait_mask_or4:
        btst.b #$6,$2(a3)
        bne.b .wait_mask_or4
        move.w #$0,$62(a3)
        move.w #$dfc,$40(a3)
        move.l a4,$50(a3)
        move.l a2,$4c(a3)
        move.l a2,$54(a3)
        move.w d4,$58(a3)
        lea.l (_display+DisplayData_blit_mask).l,a2
.wait_before_draw:
        btst.b #$6,$2(a3)
        bne.b .wait_before_draw
        move.w d3,$44(a3)
        swap d3
        move.w d3,$46(a3)
        add.w d6,d6
        move.w #$28,d1
        sub.w d6,d1
        neg.w d6
        tst.b d2
        bne.w .wait_shifted_draw
        move.w #$fca,d2
        move.w d2,$40(a3)
        moveq #$ff,d7
        move.w d7,$46(a3)
        addq.w #$1,d7
        move.w d7,$64(a3)
        move.w d7,$42(a3)
        add.w (_display+DisplayData_blit_extra_modulo).l,d7
        move.w d7,$62(a3)
.draw_planes:
        move.w d1,$60(a3)
        move.w d1,$66(a3)
        movea.l a0,a4
        movem.l a0-a2/a4,$48(a3)
        move.w d4,$58(a3)
        move.l (_display+DisplayData_blit_plane_stride).l,d7
        adda.w d7,a0
        adda.w d7,a4
        adda.w d0,a1
.wait_second_plane:
        btst.b #$6,$2(a3)
        bne.b .wait_second_plane
        movem.l a0-a2/a4,$48(a3)
        move.w d4,$58(a3)
        adda.w d7,a0
        adda.w d7,a4
        adda.w d0,a1
.wait_third_plane:
        btst.b #$6,$2(a3)
        bne.b .wait_third_plane
        movem.l a0-a2/a4,$48(a3)
        move.w d4,$58(a3)
        adda.w d7,a0
        adda.w d7,a4
        adda.w d0,a1
.wait_fourth_plane:
        btst.b #$6,$2(a3)
        bne.b .wait_fourth_plane
        movem.l a0-a2/a4,$48(a3)
        tst.b (_draw_flag).l
        beq.b .blit_image_done
        move.w d4,$58(a3)
        adda.w d7,a0
        adda.w d7,a4
        movea.l #_blank_plane,a1
.wait_fifth_plane:
        btst.b #$6,$2(a3)
        bne.b .wait_fifth_plane
        movem.l a0-a2/a4,$48(a3)
.blit_image_done:
        move.w #$400,$96(a3)
        move.w d4,$58(a3)
        movem.l (sp)+,d2-d7/a2-a4
        rts
.wait_shifted_draw:
        btst.b #$6,$2(a3)
        bne.b .wait_shifted_draw
        moveq #$c,d5
        lsl.w d5,d2
        move.w d2,$42(a3)
        ori.w #$fca,d2
        move.w d2,$40(a3)
        move.w (_display+DisplayData_blit_extra_modulo).l,d3
        bpl.b .shifted_modulo
        moveq #$0,d3
        moveq #$0,d7
        bra.b .shifted_set_modulos
.shifted_modulo:
        subq.w #$2,d1
        moveq #$fe,d7
        add.w d7,d6
        addq.w #$1,d4
.shifted_set_modulos:
        move.w d7,$64(a3)
        add.w d3,d7
        move.w d7,$62(a3)
        bra.w .draw_planes

; ---- timing loops ----
; void delay(void), the music's busy wait (inline at orig $0024F2 and $00250A): 301 rounds of a lone dbra
_delay:
        move.w #$12c,d0
.loop:
        dbra d0,.loop
        rts

; void startup_delay(void), orig $000C26: a long wait before the program starts (a register loop, 18 cycles a round)
_startup_delay:
        move.l #$f4240,d0
.loop:
        subq.l #1,d0
        bne.b .loop
        rts

; void interrupts_on(void), the original's `move #$2000,sr` at orig $000C4A: until here the program runs with all
; interrupts masked, so the vertical blank that came in the meantime is still pending and is taken at once
_interrupts_on:
        move.w #$2000,sr
        rts

; void load_next_stage(void), orig $000DC4: interrupts masked, then the loader that is still in memory (its entry at
; $0150, reached in the original through `jmp $88`, the nops and `jmp $150` at $A2) loads the next part of the game,
; which runs from $0084 as the first part did.  Does not return.
_load_next_stage:
        move.w #$2700,sr
        jmp ($150).l

; ---- the vertical blank interrupt and the music ----
; void vbl_wait(void), orig $002CDE: wait for the next vertical blank (the interrupt increments the frame count)
_vbl_wait:
        move.l d0,-(a7)
        move.w (_vblank+Vblank_count).l,d0
.loop:
        cmp.w (_vblank+Vblank_count).l,d0
        beq.w .loop
        move.l (a7)+,d0
        rts 

; orig $001DD6: the level 3 interrupt (vertical blank): the music, the clock, the fire buttons, the colours
_irq_level3:
        move.w #$2700,sr
        btst.b #$5,$dff01f.l
        beq.w .irq_clear_request
        tst.w (_flags+Flags_music_enabled).l
        beq.b .irq_clear_request
        bsr.w music_step
.irq_clear_request:
        move.w #$70,$dff09c.l
        addq.l #$1,(_game_clock+GameClock_ticks).l
        tst.w (_game_clock+GameClock_input_seen).l
        bne.b .irq_to_housekeeping
        movem.l d0-d1,-(a7)   ; the original: movem.w
        move.b $bfe001.l,d0
        move.w d0,d1
        andi.w #$80,d0
        andi.w #$40,d1
        lsl.w #$1,d1
        and.w d0,d1
        bne.b .space_check   ; no button down: look at the keyboard (patch)
.button_down:
        move.w #$1,(_flags+Flags_fire_pressed).l
        move.w #$1,(_game_clock+GameClock_input_seen).l
        bra.b .irq_buttons_done
; patch: the space bar counts as a fire button
.space_check:
        move.b $bfed01.l,d0         ; CIA-A interrupt flags (reading clears them); bit 3: a keyboard byte has arrived
        btst #$3,d0
        beq.b .irq_buttons_done
        move.b $bfec01.l,d0         ; the byte: the key code rotated left, inverted
        ori.b #$40,$bfee01.l        ; acknowledge it: pull the serial line low (control register A, SPMODE) ...
        moveq #$3c,d1
.keyboard_acknowledge:
        dbra d1,.keyboard_acknowledge   ; ... for 61 rounds, 85 microseconds or more
        andi.b #$bf,$bfee01.l
        not.b d0
        ror.b #$1,d0                ; the key code, bit 7 set for a key that goes up
        cmpi.b #$40,d0              ; space down
        beq.b .button_down
.irq_buttons_done:
        movem.l (a7)+,d0-d1   ; the original: movem.w
.irq_to_housekeeping:
        jmp (irq_housekeeping).l
irq_housekeeping:
        movem.l d0-d7/a0-a6,-(a7)
        lea.l $dff000.l,a6
        tst.w (_vblank+Vblank_palette_dirty).l
        beq.w .irq_count_frames
        clr.w (_vblank+Vblank_palette_dirty).l
        lea.l (_display+DisplayData_palette_colour).l,a0
        lea.l $dff180.l,a1
        movem.l (a0),d0-d7
        movem.l d0-d7,(a1)
        movem.l $20(a0),d0-d7
        movem.l d0-d7,$20(a1)
.irq_count_frames:
        cmpi.w #$7fff,(_vblank+Vblank_saturating).l
        beq.w .irq_count_vblanks
        addq.w #$1,(_vblank+Vblank_saturating).l
.irq_count_vblanks:
        addq.w #$1,(_vblank+Vblank_count).l
        movem.l (a7)+,d0-d7/a0-a6
        rte 

; void music_init(void), orig $002242: find the sample data, record each sample's address, silence the channels
_music_init:
        movem.l d2-d7/a2-a6,-(sp)
        lea.l (_module).l,a0
        movea.l a0,a1
        adda.l #$3b8,a1
        moveq #$7f,d0
        moveq #$0,d1
.find_last_pattern:
        move.l d1,d2
        subq.w #$1,d0
.scan_order_table:
        move.b (a1)+,d1
        cmp.b d2,d1
        bgt.b .find_last_pattern
        dbra d0,.scan_order_table
        addq.b #$1,d2
        lea.l (Addr_sample_start).w,a1
        asl.l #$8,d2
        asl.l #$2,d2
        addi.l #$43c,d2
        add.l a0,d2
        movea.l d2,a2
        moveq #$1e,d0
.locate_samples:
        clr.l (a2)
        move.l a2,(a1)+
        moveq #$0,d1
        move.w $2a(a0),d1
        asl.l #$1,d1
        adda.l d1,a2
        adda.l #$1e,a0
        dbra d0,.locate_samples
        move.b #$6,(_music+MusicState_speed).l
        clr.w $dff0a8.l
        clr.w $dff0b8.l
        clr.w $dff0c8.l
        clr.w $dff0d8.l
        clr.b (_music+MusicState_order).l
        clr.b (_music+MusicState_tick).l
        clr.w (_music+MusicState_row).l
        movem.l (sp)+,d2-d7/a2-a6
        rts
music_stop:
        clr.w $dff0a8.l
        clr.w $dff0b8.l
        clr.w $dff0c8.l
        clr.w $dff0d8.l
        move.w #$f,$dff096.l
        movem.l (sp)+,d2-d7/a2-a6
        rts

; orig $0022E6: advance the music by one tick (called by the interrupt)
music_step:
        movem.l d0-d4/a0-a3/a5-a6,-(a7)
        lea.l (_module).l,a0
        addq.b #$1,(_music+MusicState_tick).l
        move.b (_music+MusicState_tick).l,d0
        cmp.b (_music+MusicState_speed).l,d0
        blt.b .tick_effects
        clr.b (_music+MusicState_tick).l
        bra.w new_row
.tick_effects:
        lea.l (Addr_channel).w,a6
        lea.l $dff0a0.l,a5
        bsr.w channel_tick
        lea.l (Addr_channel+Channel_size*1).w,a6
        lea.l $dff0b0.l,a5
        bsr.w channel_tick
        lea.l (Addr_channel+Channel_size*2).w,a6
        lea.l $dff0c0.l,a5
        bsr.w channel_tick
        lea.l (Addr_channel+Channel_size*3).w,a6
        lea.l $dff0d0.l,a5
        bsr.w channel_tick
        bra.w step_done
arpeggio:
        moveq #$0,d0
        move.b (_music+MusicState_tick).l,d0
        divs.w #$3,d0
        swap d0
        cmpi.w #$0,d0
        beq.b .arpeggio_base
        cmpi.w #$2,d0
        beq.b .arpeggio_low_nibble
        moveq #$0,d0
        move.b Channel_cell+3(a6),d0
        lsr.b #$4,d0
        bra.b .arpeggio_offset
.arpeggio_low_nibble:
        moveq #$0,d0
        move.b Channel_cell+3(a6),d0
        andi.b #$f,d0
        bra.b .arpeggio_offset
.arpeggio_base:
        move.w Channel_period(a6),d2
        bra.b .arpeggio_set_period
.arpeggio_offset:
        asl.w #$1,d0
        moveq #$0,d1
        move.w Channel_period(a6),d1
        lea.l (Addr_period_table).w,a0
        moveq #$24,d7
.arpeggio_find_period:
        move.w (a0,d0.w),d2
        cmp.w (a0),d1
        bge.b .arpeggio_set_period
        addq.l #$2,a0
        dbra d7,.arpeggio_find_period
        rts 
.arpeggio_set_period:
        move.w d2,AudioChannel_per(a5)
        rts 
new_row:
        lea.l (_module).l,a0
        movea.l a0,a3
        movea.l a0,a2
        adda.l #$c,a3
        adda.l #$3b8,a2
        adda.l #$43c,a0
        moveq #$0,d0
        move.l d0,d1
        move.b (_music+MusicState_order).l,d0
        move.b (a2,d0.w),d1
        asl.l #$8,d1
        asl.l #$2,d1
        add.w (_music+MusicState_row).l,d1
        clr.w (_music+MusicState_dma).l
        lea.l $dff0a0.l,a5
        lea.l (Addr_channel).w,a6
        bsr.b channel_row
        lea.l $dff0b0.l,a5
        lea.l (Addr_channel+Channel_size*1).w,a6
        bsr.b channel_row
        lea.l $dff0c0.l,a5
        lea.l (Addr_channel+Channel_size*2).w,a6
        bsr.b channel_row
        lea.l $dff0d0.l,a5
        lea.l (Addr_channel+Channel_size*3).w,a6
        bsr.b channel_row
        bra.w start_dma
channel_row:
        move.l (a0,d1.l),(a6)
        addq.l #$4,d1
        moveq #$0,d2
        move.b Channel_cell+2(a6),d2
        andi.b #$f0,d2
        lsr.b #$4,d2
        move.b (a6),d0
        andi.b #$f0,d0
        or.b d0,d2
        tst.b d2
        beq.b .row_effect
        moveq #$0,d3
        lea.l (Addr_sample_start).w,a1
        move.l d2,d4
        subq.l #$1,d2
        asl.l #$2,d2
        mulu.w #$1e,d4
        move.l (a1,d2.l),Channel_sample(a6)
        move.w (a3,d4.l),Channel_length(a6)
        move.w $2(a3,d4.l),Channel_volume(a6)
        move.w $4(a3,d4.l),d3
        tst.w d3
        beq.b .sample_no_repeat
        move.l Channel_sample(a6),d2
        asl.w #$1,d3
        add.l d3,d2
        move.l d2,Channel_loop(a6)
        move.w $4(a3,d4.l),d0
        add.w $6(a3,d4.l),d0
        move.w d0,Channel_length(a6)
        move.w $6(a3,d4.l),Channel_loop_length(a6)
        move.w Channel_volume(a6),AudioChannel_vol(a5)
        bra.b .row_effect
.sample_no_repeat:
        move.l Channel_sample(a6),d2
        add.l d3,d2
        move.l d2,Channel_loop(a6)
        move.w $6(a3,d4.l),Channel_loop_length(a6)
        move.w Channel_volume(a6),AudioChannel_vol(a5)
.row_effect:
        move.w (a6),d0
        andi.w #$fff,d0
        beq.w row_command
        move.b Channel_cell+2(a6),d0
        andi.b #$f,d0
        cmpi.b #$3,d0
        bne.b .start_note
        bsr.w tone_portamento_target
        bra.w row_command
.start_note:
        move.w (a6),Channel_period(a6)
        andi.w #$fff,Channel_period(a6)
        move.w Channel_dma(a6),d0
        move.w d0,$dff096.l
        clr.b Channel_vibrato_pos(a6)
        move.l Channel_sample(a6),(a5)
        move.w Channel_length(a6),AudioChannel_len(a5)
        move.w Channel_period(a6),d0
        andi.w #$fff,d0
        move.w d0,AudioChannel_per(a5)
        move.w Channel_dma(a6),d0
        or.w d0,(_music+MusicState_dma).l
        bra.w row_command
start_dma:
        move.w #$12c,d0
.start_dma_wait1:
        dbra d0,.start_dma_wait1
        move.w (_music+MusicState_dma).l,d0
        ori.w #$8000,d0
        move.w d0,$dff096.l
        move.w #$12c,d0
.start_dma_wait2:
        dbra d0,.start_dma_wait2
        lea.l $dff000.l,a5
        lea.l (Addr_channel+Channel_size*3).w,a6
        move.l Channel_loop(a6),$d0(a5)
        move.w Channel_loop_length(a6),$d4(a5)
        lea.l (Addr_channel+Channel_size*2).w,a6
        move.l Channel_loop(a6),$c0(a5)
        move.w Channel_loop_length(a6),$c4(a5)
        lea.l (Addr_channel+Channel_size*1).w,a6
        move.l Channel_loop(a6),$b0(a5)
        move.w Channel_loop_length(a6),$b4(a5)
        lea.l (Addr_channel).w,a6
        move.l Channel_loop(a6),$a0(a5)
        move.w Channel_loop_length(a6),$a4(a5)
        addi.w #$10,(_music+MusicState_row).l
        cmpi.w #$400,(_music+MusicState_row).l
        bne.b step_done
next_order:
        clr.w (_music+MusicState_row).l
        clr.b (_music+MusicState_jump).l
        addq.b #$1,(_music+MusicState_order).l
        andi.b #$7f,(_music+MusicState_order).l
        move.b (_music+MusicState_order).l,d1
        cmp.b (_module+Module_song_length).l,d1
        bne.b step_done
        clr.b (_music+MusicState_order).l
step_done:
        tst.b (_music+MusicState_jump).l
        bne.b next_order
        movem.l (a7)+,d0-d4/a0-a3/a5-a6
        rts 
tone_portamento_target:
        move.w (a6),d2
        andi.w #$fff,d2
        move.w d2,Channel_porta_target(a6)
        move.w Channel_period(a6),d0
        clr.b Channel_porta_down(a6)
        cmp.w d0,d2
        beq.b .portamento_target_reached
        bge.b portamento_done
        move.b #$1,Channel_porta_down(a6)
        rts 
.portamento_target_reached:
        clr.w Channel_porta_target(a6)
portamento_done:
        rts 
tone_portamento:
        move.b Channel_cell+3(a6),d0
        beq.b .tone_portamento_step
        move.b d0,Channel_porta_speed(a6)
        clr.b Channel_cell+3(a6)
.tone_portamento_step:
        tst.w Channel_porta_target(a6)
        beq.b portamento_done
        moveq #$0,d0
        move.b Channel_porta_speed(a6),d0
        tst.b Channel_porta_down(a6)
        bne.b .tone_portamento_down
        add.w d0,Channel_period(a6)
        move.w Channel_porta_target(a6),d0
        cmp.w Channel_period(a6),d0
        bgt.b .portamento_set_period
        move.w Channel_porta_target(a6),Channel_period(a6)
        clr.w Channel_porta_target(a6)
.portamento_set_period:
        move.w Channel_period(a6),AudioChannel_per(a5)
        rts 
.tone_portamento_down:
        sub.w d0,Channel_period(a6)
        move.w Channel_porta_target(a6),d0
        cmp.w Channel_period(a6),d0
        blt.b .portamento_set_period
        move.w Channel_porta_target(a6),Channel_period(a6)
        clr.w Channel_porta_target(a6)
        move.w Channel_period(a6),AudioChannel_per(a5)
        rts 
vibrato:
        move.b Channel_cell+3(a6),d0
        beq.b .vibrato_apply
        move.b d0,Channel_vibrato(a6)
.vibrato_apply:
        move.b Channel_vibrato_pos(a6),d0
        lea.l (Addr_vibrato_table).w,a4
        lsr.w #$2,d0
        andi.w #$1f,d0
        moveq #$0,d2
        move.b (a4,d0.w),d2
        move.b Channel_vibrato(a6),d0
        andi.w #$f,d0
        mulu.w d0,d2
        lsr.w #$6,d2
        move.w Channel_period(a6),d0
        tst.b Channel_vibrato_pos(a6)
        bmi.b .vibrato_subtract
        add.w d2,d0
        bra.b .vibrato_set_period
.vibrato_subtract:
        sub.w d2,d0
.vibrato_set_period:
        move.w d0,AudioChannel_per(a5)
        move.b Channel_vibrato(a6),d0
        lsr.w #$2,d0
        andi.w #$3c,d0
        add.b d0,Channel_vibrato_pos(a6)
        rts 
set_period:
        move.w Channel_period(a6),AudioChannel_per(a5)
        rts 
channel_tick:
        move.w Channel_cell+2(a6),d0
        andi.w #$fff,d0
        beq.b set_period
        move.b Channel_cell+2(a6),d0
        andi.b #$f,d0
        tst.b d0
        beq.w arpeggio
        cmpi.b #$1,d0
        beq.b .portamento_up
        cmpi.b #$2,d0
        beq.w .portamento_down
        cmpi.b #$3,d0
        beq.w tone_portamento
        cmpi.b #$4,d0
        beq.w vibrato
        move.w Channel_period(a6),AudioChannel_per(a5)
        cmpi.b #$a,d0
        beq.b .volume_slide
        rts 
.volume_slide:
        moveq #$0,d0
        move.b Channel_cell+3(a6),d0
        lsr.b #$4,d0
        tst.b d0
        beq.b .volume_slide_down
        add.w d0,Channel_volume(a6)
        cmpi.w #$40,Channel_volume(a6)
        bmi.b .volume_slide_write
        move.w #$40,Channel_volume(a6)
.volume_slide_write:
        move.w Channel_volume(a6),AudioChannel_vol(a5)
        rts 
.volume_slide_down:
        moveq #$0,d0
        move.b Channel_cell+3(a6),d0
        andi.b #$f,d0
        sub.w d0,Channel_volume(a6)
        bpl.b .volume_slide_down_write
        clr.w Channel_volume(a6)
.volume_slide_down_write:
        move.w Channel_volume(a6),AudioChannel_vol(a5)
        rts 
.portamento_up:
        moveq #$0,d0
        move.b Channel_cell+3(a6),d0
        sub.w d0,Channel_period(a6)
        move.w Channel_period(a6),d0
        andi.w #$fff,d0
        cmpi.w #$71,d0
        bpl.b .portamento_up_write
        andi.w #$f000,Channel_period(a6)
        ori.w #$71,Channel_period(a6)
.portamento_up_write:
        move.w Channel_period(a6),d0
        andi.w #$fff,d0
        move.w d0,AudioChannel_per(a5)
        rts 
.portamento_down:
        clr.w d0
        move.b Channel_cell+3(a6),d0
        add.w d0,Channel_period(a6)
        move.w Channel_period(a6),d0
        andi.w #$fff,d0
        cmpi.w #$358,d0
        bmi.b .portamento_down_write
        andi.w #$f000,Channel_period(a6)
        ori.w #$358,Channel_period(a6)
.portamento_down_write:
        move.w Channel_period(a6),d0
        andi.w #$fff,d0
        move.w d0,AudioChannel_per(a5)
        rts 
row_command:
        move.b Channel_cell+2(a6),d0
        andi.b #$f,d0
        cmpi.b #$e,d0
        beq.b .command_extended
        cmpi.b #$d,d0
        beq.b .command_pattern_break
        cmpi.b #$b,d0
        beq.b .command_position_jump
        cmpi.b #$c,d0
        beq.b .command_volume
        cmpi.b #$f,d0
        beq.b .command_speed
        rts 
.command_extended:
        rts 
.command_pattern_break:
        not.b (_music+MusicState_jump).l
        rts 
.command_position_jump:
        move.b Channel_cell+3(a6),d0
        subq.b #$1,d0
        move.b d0,(_music+MusicState_order).l
        not.b (_music+MusicState_jump).l
        rts 
.command_volume:
        cmpi.b #$40,Channel_cell+3(a6)
        ble.b .command_volume_write
        move.b #$40,Channel_cell+3(a6)
.command_volume_write:
        move.b Channel_cell+3(a6),AudioChannel_vol(a5)
        rts 
.command_speed:
        move.b Channel_cell+3(a6),d0
        andi.w #$1f,d0
        beq.b .command_done
        clr.b (_music+MusicState_tick).l
        move.b d0,(_music+MusicState_speed).l
.command_done:
        rts 
